CREATE OR REPLACE FUNCTION current_church_unit() RETURNS TABLE(unit_type text, network_id uuid, region_id uuid, billing_account_id uuid) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT c.unit_type,c.network_id,c.region_id,c.billing_account_id FROM churches c WHERE c.id=tenant_id() $$;
CREATE OR REPLACE FUNCTION membership_in_current_church(p_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT EXISTS(SELECT 1 FROM memberships WHERE church_id=tenant_id() AND user_id=p_user) $$;
CREATE OR REPLACE FUNCTION create_congregation(p_name text,p_region uuid,p_admin uuid) RETURNS TABLE(id uuid,name text,unit_type text,parent_church_id uuid,billing_account_id uuid) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE parent churches%ROWTYPE; child churches%ROWTYPE; BEGIN SELECT * INTO parent FROM churches WHERE churches.id=tenant_id(); IF parent.id IS NULL OR parent.unit_type<>'sede' OR local_role()<>'admin' THEN RAISE EXCEPTION 'Not authorized'; END IF; INSERT INTO churches(network_id,region_id,name,unit_type,parent_church_id,billing_account_id) VALUES(parent.network_id,COALESCE(p_region,parent.region_id),p_name,'congregacao',parent.id,parent.billing_account_id) RETURNING * INTO child; INSERT INTO campuses(church_id,name) VALUES(child.id,'Sede da congregação'); IF p_admin IS NOT NULL THEN IF NOT EXISTS(SELECT 1 FROM users WHERE users.id=p_admin) THEN RAISE EXCEPTION 'Administrator not found'; END IF; INSERT INTO memberships(user_id,church_id,role) VALUES(p_admin,child.id,'admin'); END IF; RETURN QUERY SELECT child.id,child.name,child.unit_type,child.parent_church_id,child.billing_account_id; END $$;
CREATE OR REPLACE FUNCTION update_congregation(p_id uuid,p_name text,p_active boolean) RETURNS TABLE(id uuid,name text,unit_type text,parent_church_id uuid,active boolean,billing_account_id uuid) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE parent churches%ROWTYPE; v churches%ROWTYPE; BEGIN SELECT * INTO parent FROM churches WHERE churches.id=tenant_id(); IF parent.id IS NULL OR parent.unit_type<>'sede' OR local_role()<>'admin' THEN RAISE EXCEPTION 'Not authorized'; END IF; UPDATE churches SET name=COALESCE(p_name,name),active=COALESCE(p_active,active) WHERE churches.id=p_id AND churches.parent_church_id=parent.id RETURNING * INTO v; IF v.id IS NULL THEN RAISE EXCEPTION 'Not found'; END IF; RETURN QUERY SELECT v.id,v.name,v.unit_type,v.parent_church_id,v.active,v.billing_account_id; END $$;
GRANT EXECUTE ON FUNCTION current_church_unit(),membership_in_current_church(uuid),create_congregation(text,uuid,uuid),update_congregation(uuid,text,boolean) TO ecclesia_app;
